import pandas as pd
import numpy as np
from collections import Counter
from sklearn.model_selection import train_test_split
import re
import os
import num2words

# Set random seed for reproducibility
np.random.seed(42)

# Suppress num2words warnings
import warnings

warnings.filterwarnings("ignore", category=DeprecationWarning)

# Load data
train_df = pd.read_csv("./input/en_train.csv")
test_df = pd.read_csv("./input/en_test_2.csv")
sample_sub = pd.read_csv("./input/en_sample_submission_2.csv")

# Create id column for test (same format as submission)
test_df["id"] = (
    test_df["sentence_id"].astype(str) + "_" + test_df["token_id"].astype(str)
)

# Step 1: Build dictionary from training data: before -> most frequent after
before_to_after = {}
for _, row in train_df.iterrows():
    before = str(row["before"]) if pd.notna(row["before"]) else ""
    after = str(row["after"]) if pd.notna(row["after"]) else ""
    if before not in before_to_after:
        before_to_after[before] = Counter()
    before_to_after[before].update([after])


# For predictions, map each before to its most common after in training
def predict_from_dict(before_token):
    before_token = str(before_token) if pd.notna(before_token) else ""
    if before_token in before_to_after and before_to_after[before_token]:
        return before_to_after[before_token].most_common(1)[0][0]
    return None


# Comprehensive fallback normalization using num2words and regex patterns
def normalize_semiotic(before_token):
    before_token = str(before_token) if pd.notna(before_token) else ""

    # Punctuation
    if re.fullmatch(r'[.,"\'?!;:]', before_token):
        return before_token

    # Cardinal numbers
    if re.fullmatch(r"\d+", before_token):
        try:
            return num2words.num2words(int(before_token))
        except:
            return before_token

    # Ordinal numbers (e.g., "1st", "2nd", "3rd", "4th")
    if re.fullmatch(r"\d+(st|nd|rd|th)", before_token):
        try:
            num = int(before_token[:-2])
            return num2words.num2words(num, to="ordinal")
        except:
            return before_token

    # Currency (e.g., "$3.16", "$100")
    if re.fullmatch(r"\$\d+(\.\d+)?", before_token):
        try:
            amount = float(before_token[1:])
            dollars = int(amount)
            cents = round((amount - dollars) * 100)
            if dollars > 0 and cents > 0:
                return f"{num2words.num2words(dollars)} dollars, {num2words.num2words(cents)} cents"
            elif dollars > 0:
                return f"{num2words.num2words(dollars)} dollars"
            elif cents > 0:
                return f"{num2words.num2words(cents)} cents"
            else:
                return "zero dollars"
        except:
            return before_token

    # Percentages (e.g., "15%", "3.5%")
    if re.fullmatch(r"\d+(\.\d+)?%", before_token):
        try:
            num = float(before_token[:-1])
            return num2words.num2words(num) + " percent"
        except:
            return before_token

    # Decimals (e.g., "3.14", "100.0")
    if re.fullmatch(r"\d+\.\d+", before_token):
        try:
            return num2words.num2words(float(before_token))
        except:
            return before_token

    # Time expressions (e.g., "12:47", "3:05", "08:00")
    if re.fullmatch(r"\d{1,2}:\d{2}", before_token):
        try:
            parts = before_token.split(":")
            hour = int(parts[0])
            minute = int(parts[1])
            if minute == 0:
                return num2words.num2words(hour) + " o'clock"
            elif minute < 10:
                return num2words.num2words(hour) + " oh " + num2words.num2words(minute)
            else:
                return num2words.num2words(hour) + " " + num2words.num2words(minute)
        except:
            return before_token

    # Dates in common formats (e.g., "12/25/2023", "25/12/2023")
    if re.fullmatch(r"\d{1,2}/\d{1,2}/\d{4}", before_token):
        try:
            parts = before_token.split("/")
            # Assume MM/DD/YYYY for US format
            month, day, year = int(parts[0]), int(parts[1]), int(parts[2])
            return (
                num2words.num2words(month, to="ordinal")
                + " "
                + num2words.num2words(day)
                + " "
                + num2words.num2words(year)
            )
        except:
            return before_token

    # Fractions (e.g., "1/2", "3/4")
    if re.fullmatch(r"\d+/\d+", before_token):
        try:
            parts = before_token.split("/")
            num = int(parts[0])
            denom = int(parts[1])
            return (
                f"{num2words.num2words(num)} {num2words.num2words(denom, suffix='th')}"
            )
        except:
            return before_token

    return None  # Let caller handle unknown tokens


# Predict on validation set to compute accuracy
train_tok, val_tok = train_test_split(train_df, test_size=0.05, random_state=42)

val_preds = []
for _, row in val_tok.iterrows():
    before_token = str(row["before"]) if pd.notna(row["before"]) else ""
    after_true = str(row["after"]) if pd.notna(row["after"]) else ""

    pred = predict_from_dict(before_token)
    if pred is None:
        pred = normalize_semiotic(before_token)
    if pred is None:
        pred = before_token  # fallback

    val_preds.append(pred)

# Compute accuracy: exact match
val_actual = [
    str(row["after"]) if pd.notna(row["after"]) else "" for _, row in val_tok.iterrows()
]
accuracy = sum([p == a for p, a in zip(val_preds, val_actual)]) / len(val_actual)
print(f"Validation accuracy: {accuracy:.6f}")

# Now make predictions for the test set
test_predictions = []
for _, row in test_df.iterrows():
    before_token = str(row["before"]) if pd.notna(row["before"]) else ""
    pred = predict_from_dict(before_token)
    if pred is None:
        pred = normalize_semiotic(before_token)
    if pred is None:
        pred = before_token  # fallback for truly unknown tokens
    test_predictions.append(pred)

# Create submission file
submission = pd.DataFrame({"id": test_df["id"], "after": test_predictions})

# Ensure submission directory exists
os.makedirs("./submission", exist_ok=True)
submission.to_csv("./submission/submission.csv", index=False)

print("Submission saved to ./submission/submission.csv")
